INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q26493', 'Battle of Dandanaqan', 'The Battle of Dandanaqan (Persian: نبرد دندانقان) was fought in 1040 between the Seljuq Turkmens and the Ghaznavid Empire near the city of Merv (now in Turkmenistan). The battle ended with a decisive Seljuq victory, which subsequently brought down the Ghaznavid domination in Greater Khorasan.', 1040, 5, 23, NULL, NULL, NULL, 'day', '23 May 1040', 62, 'https://en.wikipedia.org/wiki/Battle_of_Dandanaqan'),
  ('Q39081822', 'Siege of Merv', 'The siege of Merv (Persian: محاصره مرو) took place in April 1221, during the Mongol invasion of Khorasan. In 1219, Genghis Khan, ruler of the Mongol Empire, invaded the Khwarazmian Empire ruled by Shah Muhammad II. While the Shah planned to defend his major cities individually and divided his army to station in several garrisons, the Mongols laid siege to one town after another deep into Khorasan, heart of the Khwarazmian Empire.', 1221, 4, NULL, NULL, NULL, NULL, 'month', 'April 1221', 39, 'https://en.wikipedia.org/wiki/Siege_of_Merv_(1221)'),
  ('Q4132831', 'Battle of Merv', 'The Battle of Merv (Persian: نبرد مرو) occurred on 2 December 1510 as a result of Shah Ismail I''s Safavid invasion of the Khorasan region of Uzbek. It ended with Safavid annexation of the Khorasan region.', 1510, 12, 2, NULL, NULL, NULL, 'day', '2 December 1510', 48, 'https://en.wikipedia.org/wiki/Battle_of_Merv'),
  ('Q3636447', 'Battle of Geok Tepe', 'The Battle of Geok Tepe in 1881 was the main event in the 1880/81 Russian campaign to conquer the Teke tribe of Turkmens. Its effect was to give the Russian Empire control over most of what is now Turkmenistan, thereby nearly completing the Russian conquest of Central Asia.', 1880, 12, NULL, 1881, 1, NULL, 'month', 'December 1880 – January 1881', 56, 'https://en.wikipedia.org/wiki/Battle_of_Geok_Tepe'),
  ('Q4562427', '1929 Koppeh Dagh earthquake', 'The 1929 Kopet Dag earthquake (also called the 1929 Koppeh Dagh earthquake) took place at 15:37 UTC on 1 May with a moment magnitude of 7.2 and a maximum Mercalli intensity of IX (Violent). It occurred in the Kopet Dag area of Iran and caused up to 3,800 casualties along the Iran-Turkmenistan border.', 1929, 5, 1, NULL, NULL, NULL, 'day', '1 May 1929', 34, 'https://en.wikipedia.org/wiki/1929_Kopet_Dag_earthquake'),
  ('Q2391429', '1948 Ashgabat earthquake', 'The 1948 Ashgabat earthquake was on 6 October with a surface-wave magnitude of 7.3 and a maximum Mercalli intensity of X (Extreme), in Turkmenistan near Ashgabat. Due to censorship by the Soviet government, the event was not widely reported in the Soviet media.', 1948, 10, 6, NULL, NULL, NULL, 'day', '6 October 1948', 64, 'https://en.wikipedia.org/wiki/1948_Ashgabat_earthquake'),
  ('Q7855457', 'Turkmenistani presidential term referendum, 1994', 'A referendum on extending President Saparmurat Niyazov''s term until 2002 was held in Turkmenistan on 15 January 1994. Official results showed that the proposal was approved by 99.99% of voters with a 100% turnout.', 1994, 1, 15, NULL, NULL, NULL, 'day', '15 January 1994', 41, 'https://en.wikipedia.org/wiki/1994_Turkmen_presidential_term_referendum');

